  "text": "凝血障碍性疾病血友病～APTT凝血活酶时间：男性多见、与遗传密切，表现为肌肉血肿、关节出血、内脏出血多见\n72 （2）血友病（缺乏凝血因子8、9、11）：APTT延长、PT正常、BT（出血时间）正常",
  "id": "k148"
