  "text": "血管性血友病（vwFI→8↓）：APTT延长、PT正常、BT（出血时间）延长\n73 （1）电解质对于糖尿病并发症诊断无意义，高渗高血糖综合征不是电解质导致的高渗透压，而是高血糖",
