  "no": 153,
  "text": "犯）；多发（≥3个关节区）、呈对称性、持续性、时轻时重\n抗dsDNA抗体\n抗DNA抗体\n抗ssDNA抗体\n抗组蛋白抗体 AHA抗体\n抗DNA组蛋白抗体 抗核小体抗体\n76 抗核抗体ANA\n抗非组蛋白抗体【抗ENA抗体】\n抗核仁抗体 约20%~40%的SSc患者抗核仁抗体阳性",
