  "no": 158,
  "text": "腹腔间隔室综合征：膀胱内压>20mmHg→诊断；>25mmHg开腹手术 “2025”\n79 （1）嗜铬细胞瘤：90%发生在肾上腺髓质（其次为腹主动脉旁）90%呈散发性（主要分泌去甲肾）、90%为良性肿瘤，可治愈",
