  "text": "表现为上肢或下肢麻木无力、僵硬，双足踩棉花感，束带感，双手精细动作障碍，后期可出现二便功能障碍\n检查有感觉障碍平面，肌力减退，四肢腱反射活跃或亢进，而浅反射减弱/消失，Hoffmann征、Babinski征等病理征呈阳性",
  "id": "k175"
