  "text": "组织水肿\n①甲减、甲亢：粘液/非凹陷性水肿\n②过敏（漏出液）炎症（感染、烧伤-渗出液）：血管通透性个\n③丝虫病、丹毒、乳腺癌橘皮样变：淋巴回流受阻",
