  "text": "急性梗阻性化脓性胆管炎AOSC：PTCD（经皮肝穿刺胆道引流术）、ENBD（鼻胆管引流）、胆总管切开减压+T管引流\n116 （1）消化道穿孔、肠梗阻、胆囊炎、肠系膜缺血和腮腺炎等疾病时血淀粉酶可升高【血清脂肪酶升高作为胰腺炎诊断指标】\n117 （2）胰腺假性囊肿：纤维组织增生（1个月左右）、缺乏上皮细胞、囊内含胰酶且和严重程度相关\n118 （1）骨肉瘤（最常见的恶性骨肿瘤）：好发于青少年长骨干骺端（股骨下端/胫骨上端等），呈溶骨性破坏，形成瘤骨（碱性磷酸\n119 酶↑），骨膜反应（Codman三角、日光射线），治疗→化疗+根治性手术+化疗；易转移至肺：术前拍胸片、可手术切除转移\n120 灶“Cod三角日光线，手术放在化疗间”",
