  "text": "骨骼肌收缩的影响因素：\n①前负荷↑一→一定范围内收缩张力↑机制：与肌动蛋白结合的横桥数目（粗细肌丝的重叠程度）\n②后负荷↑一→骨骼肌的收缩张力↑，肌肉收缩速度，肌肉缩短程度」，开始收缩的时间延迟（缩短起始时问延长）\n后负荷影响肌肉收缩速度的机制：横桥周期长短【等长收缩时间延长，等张收缩时间缩短】\n③等长收缩和等张收缩：骨骼肌收缩时先等长收缩后等张收缩，先等长增加张力后克服阻力肌肉缩短\n121 （2）心搏出量的影响因素：前负荷、后负荷、心肌收缩能力\n122 ①后负荷个一→射血时心室肌收缩速度和程度」（类比骨骼肌）、等容收缩期个（类比等长调节）、等容收缩期室内压峰值个、\n射血期|一→搏出量【瞬间】一→心室收缩末期容积↑一心室舒张末期容积（前负荷）↑→搏出量↑【异长自身调节】\n→心肌收缩能力个→搏出量↑【等长调节】【代偿】\n②主动脉压在80-170mmHg变化时，搏出量不会发生明显变化★\n③大动脉血压↑（后负荷↑动脉血压高需要蓄力射血）→射血期缩短A2↑\n④主动脉狭窄（后负荷个瓣膜狭窄动脉血压低不需等容收缩期蓄力）一→射血期延长一→消耗能量与氧气一→心绞痛A2+",
