  "text": "②促进铁的吸收：铁的吸收与机体对铁的需要量有关。当服用相同剂量的铁后，缺铁患者比正常人铁的吸收量高2～5\n倍；VitC（还原）、HCI（溶解）\n③储存在粘膜中的Fe是铁吸收的抑制因素（负反馈）",
