  "text": "成熟红细胞代谢：\n160 ①糖无氧氧化：1,3-DPG经旁路2,3-DPG：降低Hb和O亲和力（主要）供能（重新回到无氧氧化）\n②磷酸戊糖途径一5-磷酸核糖（合成核苷酸）、NADPH",
  "id": "k557"
