  "text": "跨膜生长因子受体：EGFR/HER1/ERBB1、HER2/ERBB2、FMS、KIT、TRK“福尔摩斯朵三个前女友”\n161 （3）细胞内信号转导分子：胞质或核内酪氨酸激酶（SRC、ABL等），MAPK通路重要分子（RAS、RAF等）",
