  "text": "肠外营养PN适应证：1周以上不能进食或胃肠道功能障碍、肠内营养无法达标：短肠综合征、溃疡性结肠炎长期腹泻、重\n症胰腺炎（可引起全身炎症反应综合征）、严重感染、严重烧伤、恶性肿瘤放化疗期间严重呕吐、高位小肠瘘、急性肾衰",
