  "text": "喉上神经外支损伤：音调降低【环甲肌瘫】\n一侧喉返神经损伤：声音嘶哑\n双侧喉返神经损伤：失声、呼吸困难“一侧嘶，双侧死”\n颈交感神经损伤：Horner综合征（患侧眼脸下垂、瞳孔缩小、眼球内陷、额面部胸壁无汗）",
