  "text": "乳腺癌的发病机制尚未完全阐明：雌激素长期作用（月经早、绝经晚、晚育不育、肥胖-芳香化酶）、家族遗传倾向、环境因\n177 素及长时间大剂量接触放射线和乳腺癌发病有关（BRCA1点突变或缺失和具有遗传倾向的乳腺癌发病相关）",
