  "text": "①根据红细胞膜上是否存在A 抗原和B 抗原，可将血液分为4 种ABO 血型：只含\nA 抗原者为A 型，只含B 抗原者为B 型，含有A 与B 两种抗原者为AB 型，A 和\nB 两种抗原均无者为0 型。A 抗原、B 抗原都是在H 抗原基础上形成的，0 型红细\n胞虽然不含A 抗原和B 抗原，但含有H 抗原。\n②D 抗原是Rh 血型系统的分型依据之一。",
