  "year": 2016,
  "qnum": 125,
  "no": 656,
  "text": "由于躯干四肢部分的感觉为交叉性投射，且下肢的投射区域位于中央后回顶部，故刺激\n动物右侧坐骨神经（下肢神经）时，在大脑皮层可见最大幅度诱发电位的部位是左侧中\n央后回顶部。\n故本题选择A 项",
