  "text": "●牵张反射\n●牵张反射的过程\n①骨骼肌受外力牵拉伸长（梭外肌伸长）→肌梭被拉长→Ⅰa 类传入纤维放电↑→支配同\n一肌肉的α运动神经元兴奋→梭外肌收缩（缩短）→牵张反射（对抗牵拉）（B 错A 对）\n②当α运动神经元兴奋使梭外肌缩短时→肌梭缩短→Ⅰa 类传入纤维放电↓（C 错）\n③γ运动神经元平时持续放电→梭内肌收缩→牵拉肌梭→Ⅰa 类传入纤维放电↑→肌梭对\n牵拉刺激的敏感性↑（加强牵张反射）（D 对）\n●故本题选AD",
