  "no": 662,
  "text": "：能改善帕金森病运动减少症状的药物是左旋多巴（D 对）。\n：利血平（C 错）用于亨廷顿舞蹈病的治疗。\n：哌唑嗪（B 错）和育亨宾（A 错）分别为α1 和α2 受体拮抗药，前者可用于轻、中度\n高血压的治疗，后者多用于性功能勃起障碍的治疗。\n：故本题选择D 项。\n：注意：帕金森病症状中的静止性震颤用左旋多巴和M 受体拮抗剂无效",
