  "text": "受体分为膜受体和胞内受体两类。胞内受体也称为核受体，是指定位于细胞质或细胞核\n中的受体。类固醇激素结合的受体属于核受体。酪氨酸激酶受体、G 蛋白耦联受体、鸟\n苷酸环化酶受体均属于膜受体。\n●故本题选择B 项",
