  "year": 2024,
  "qnum": 34,
  "no": 689,
  "text": "动脉粥样硬化的基本病理变化包括脂纹、纤维斑块、粥样斑块等。泡沫细胞聚集形成脂\n纹，大量胶原纤维沉积形成纤维斑块，纤维帽下大量胆固醇结晶、钙盐沉积等形成粥样\n斑块，因此脂纹是动脉粥样硬化肉眼可见的最早病变。\n●故本题选择A 项",
