  "text": "冠状动脉粥样硬化性心脏病：冠状动脉性心脏病（CHD）简称冠心病，是因冠状动脉狭\n窄所致心肌缺血而引起，也称为缺血性心脏病。心肌梗死（MI）是由于冠状动脉供血\n中断，致供血区持续缺血而导致的较大范围的心肌坏死。\n˜故本题选择C 项",
