  "no": 691,
  "text": "①原发性高血压分为良性高血压和恶性高血压，平常所说的“高血压病”常指良性高血\n压，其基本病理变化是细小动脉硬化，表现为细小动脉玻璃样变性，最易累及肾入球\n动脉、视网膜动脉、脾中心动脉。恶性高血压的特征性病变是肾入球小动脉纤维素样坏\n死。②心肌梗死最常见的病因是冠状动脉粥样硬化，最常累及左冠状动脉前降支。\n●故本题选择A 项",
